get_checkout_page.code:
const response = await client.checkoutPage.getCheckoutPage();
const settings = response.map.checkout_page;
console.log(settings.customer_checkout.allow_sign_in, settings.delivery_options.enable_store_pickup);
console.log(settings.order_summary.show_product_thumbnail);

patch_checkout_page.code:
const response = await client.checkoutPage.patchCheckoutPage({
    checkout_page: {
        order_summary: {enable_payment_expand_view: false},
        customer_checkout: {multiple_shipping_methods: true},
    },
});
const settings = response.map.checkout_page;
console.log(settings.order_summary.enable_payment_expand_view, settings.customer_checkout.multiple_shipping_methods);

get_checkout_page_section.code:
const response = await client.checkoutPage.getCheckoutPageSection('order_summary');
const summary = response.map.order_summary;
console.log(summary.show_product_thumbnail, summary.show_quantity, summary.order_confirm_captcha);
